import { Block } from "@prototyp/skeletor";
import { CallOverlayService } from "modules/call/service/CallOverlayService";
import { useEffect, useState } from "react";
import { Colors } from "shared/styles";
import { ElementCallSession } from "./ElementCallSession";

type OverlayState = ReturnType<typeof CallOverlayService.getState>;

export const ElementCallOverlayHost = () => {
  const [overlayState, setOverlayState] = useState<OverlayState>(
    CallOverlayService.getState(),
  );

  useEffect(() => {
    return CallOverlayService.subscribe(setOverlayState);
  }, []);

  if (!overlayState.activeCall) return null;

  return (
    <Block
      pointerEvents={overlayState.isVisible ? "auto" : "none"}
      background={Colors.black}
      align="center"
      justify="center"
      absolute
      width="100%"
      height="100%"
      flexDirection="row"
      offsets={[0, 0, !overlayState.isVisible ? 10000 : 0, 0]}
      opacity={overlayState.isVisible ? 1 : 0}
      zIndex={9999}
    >
      <ElementCallSession
        key={overlayState.activeCall.instanceId}
        roomId={overlayState.activeCall.roomId}
        roomName={overlayState.activeCall.roomName}
      />
    </Block>
  );
};

