import {
  type ClientInterface,
  type ClientProperties,
  EncryptionState,
  EncryptionSystem,
  generateWebviewUrl,
  HeaderStyle,
  Intent,
  makeWidgetDriver,
  newVirtualElementCallWidget,
  NotificationType,
  type RoomInterface,
  type VirtualElementCallWidgetConfig,
  type VirtualElementCallWidgetProperties,
  type WidgetCapabilitiesProvider,
  type WidgetDriverAndHandle,
  type WidgetSettings,
} from "@unomed/react-native-matrix-sdk";

export class ElementCallService {
  private static widgetDrivers: Map<string, WidgetDriverAndHandle> = new Map();
  private static activeCallRoomId: string | null = null;
  private static activeCallListeners = new Set<
    (hasActiveCall: boolean) => void
  >();

  private static emitActiveCallChange() {
    const hasActiveCall = this.hasActiveCall();
    for (const listener of this.activeCallListeners) {
      listener(hasActiveCall);
    }
  }

  private static setActiveCallRoomId(roomId: string | null) {
    if (this.activeCallRoomId === roomId) return;
    this.activeCallRoomId = roomId;
    this.emitActiveCallChange();
  }

  private static setFragmentQueryParam(
    url: string,
    key: string,
    value: string,
  ): string {
    const [base, fragment = ""] = url.split("#");
    const existingQuery = fragment.startsWith("?")
      ? fragment.slice(1)
      : fragment;
    const params = new URLSearchParams(existingQuery);
    params.set(key, value);
    return `${base}#?${params.toString()}`;
  }

  private static async resolveCallIntent(room: RoomInterface): Promise<Intent> {
    const hasActiveCall = room.hasActiveRoomCall();
    const isDirect = await room.isDirect();

    if (hasActiveCall) {
      return isDirect ? Intent.JoinExistingDm : Intent.JoinExisting;
    }
    return isDirect ? Intent.StartCallDm : Intent.StartCall;
  }

  static async createWidgetSettings(roomId: string, room: RoomInterface) {
    try {
      const encryptionState = await room.latestEncryptionState();
      const isEncrypted = encryptionState === EncryptionState.Encrypted;
      const intent = await this.resolveCallIntent(room);

      const options: VirtualElementCallWidgetProperties = {
        elementCallUrl: "https://call.element.io/room",
        widgetId: `element-call-${roomId}`,
        fontScale: 1,
        parentUrl: undefined,
        font: undefined,
        encryption: isEncrypted
          ? new EncryptionSystem.PerParticipantKeys()
          : new EncryptionSystem.Unencrypted(),
        posthogApiHost: undefined,
        posthogApiKey: undefined,
        posthogUserId: undefined,
        rageshakeSubmitUrl: undefined,
        sentryDsn: undefined,
        sentryEnvironment: undefined,
      };

      const config: VirtualElementCallWidgetConfig = {
        hideHeader: true,
        preload: false,
        confineToRoom: true,
        header: HeaderStyle.None,
        appPrompt: false, // Hides "Open in App" prompt
        hideScreensharing: false,
        intent,
        sendNotificationType: NotificationType.Ring,
        skipLobby: true,
        controlledAudioDevices: false,
      };

      return newVirtualElementCallWidget(options, config);
    } catch (error) {
      console.error("Failed to create widget settings:", error);
      throw error;
    }
  }

  static async generateCallUrl(
    widgetSettings: WidgetSettings,
    room: RoomInterface,
    _client: ClientInterface,
  ) {
    // Client properties for the widget
    const clientProperties: ClientProperties = {
      clientId: "io.element.elementx", // This allows widgets to adapt to specific clients
      languageTag: "en-US",
      theme: "dark",
    };

    try {
      const url = await generateWebviewUrl(
        widgetSettings,
        room,
        clientProperties,
      );

      // Prevent Element Call from auto-closing the widget when ring pickup times out on remote clients.
      return this.setFragmentQueryParam(url, "waitForCallPickup", "false");
    } catch (error) {
      console.error("Failed to generate Element Call URL:", error);
      throw error;
    }
  }

  static initializeWidgetDriver(
    roomId: string,
    widgetSettings: WidgetSettings,
  ) {
    const driverAndHandle = makeWidgetDriver(widgetSettings);
    this.widgetDrivers.set(roomId, driverAndHandle);
    return driverAndHandle;
  }

  static createCapabilitiesProvider() {
    const provider: WidgetCapabilitiesProvider = {
      acquireCapabilities: (requestedCapabilities) => {
        // Grant what the widget is requesting, not just the base permissions
        // The widget needs state keys with _m.call suffix, but getElementCallRequiredPermissions
        // only returns keys without the suffix
        // Return the REQUESTED capabilities (which includes the correct state keys)
        return requestedCapabilities;
      },
    };

    return provider;
  }

  static async startCall(
    roomId: string,
    room: RoomInterface,
    client: ClientInterface,
  ) {
    try {
      // Check if there's already an active driver for this room
      const existingDriver = this.widgetDrivers.get(roomId);
      if (existingDriver) {
        // Return existing driver instead of creating a new one
        const widgetSettings = await this.createWidgetSettings(roomId, room);
        const url = await this.generateCallUrl(widgetSettings, room, client);
        return { url, driverHandle: existingDriver };
      }

      const widgetSettings = await this.createWidgetSettings(roomId, room);

      const driverHandle = this.initializeWidgetDriver(roomId, widgetSettings);

      const url = await this.generateCallUrl(widgetSettings, room, client);

      const capabilitiesProvider = this.createCapabilitiesProvider();

      driverHandle.driver.run(room, capabilitiesProvider).catch(console.error);

      this.setActiveCallRoomId(roomId);

      return { url, driverHandle };
    } catch (error) {
      console.error("Failed to start Element Call:", error);
      throw error;
    }
  }

  static async endCall(roomId: string) {
    try {
      const driverHandle = this.widgetDrivers.get(roomId);
      if (driverHandle) {
        const widgetId = `element-call-${roomId}`;

        try {
          // Send hangup message to Element Call
          // This tells Element Call to leave the LiveKit session and remove call.member state
          const hangupMessage = JSON.stringify({
            api: "fromWidget",
            widgetId: widgetId,
            requestId: `hangup-${Date.now()}`,
            action: "im.vector.hangup",
            data: {},
          });

          await driverHandle.handle.send(hangupMessage);

          await new Promise((resolve) => setTimeout(resolve, 1000));

          // Send close message to ensure widget cleanup
          // This is similar to what Swift does with the "close" action
          const closeMessage = JSON.stringify({
            api: "fromWidget",
            widgetId: widgetId,
            requestId: `close-${Date.now()}`,
            action: "io.element.close",
            data: {},
          });

          await driverHandle.handle.send(closeMessage);

          await new Promise((resolve) => setTimeout(resolve, 500));
        } catch (err) {
          console.error("Failed to send end call messages:", err);
        }

        // Cleanup driver
        this.widgetDrivers.delete(roomId);
      }

      if (this.activeCallRoomId === roomId) this.setActiveCallRoomId(null);
    } catch (error) {
      console.error("Failed to end call:", error);
    }
  }

  /**
   * Clean up driver without sending any messages
   * Use this when Element Call has already sent the hangup message
   */
  static async cleanupDriver(roomId: string) {
    this.widgetDrivers.delete(roomId);
    if (this.activeCallRoomId === roomId) this.setActiveCallRoomId(null);
  }

  static getActiveCallRoomId() {
    return this.activeCallRoomId;
  }

  static hasActiveCall() {
    return this.activeCallRoomId !== null;
  }

  static subscribeToActiveCallState(
    listener: (hasActiveCall: boolean) => void,
  ): () => void {
    this.activeCallListeners.add(listener);
    listener(this.hasActiveCall());
    return () => {
      this.activeCallListeners.delete(listener);
    };
  }

  /**Send message to widget via driver handle */
  static async sendMessageToWidget(roomId: string, message: string) {
    const driverHandle = this.widgetDrivers.get(roomId);

    if (!driverHandle) {
      console.warn("No driver handle found for room:", roomId);
      return;
    }

    try {
      await driverHandle.handle.send(message);
    } catch (error) {
      console.error("Failed to send message to widget:", error);
      throw error;
    }
  }

  static async receiveMessagesFromWidget(roomId: string) {
    const driverHandle = this.widgetDrivers.get(roomId);

    if (!driverHandle) {
      console.warn("No driver handle found for room:", roomId);
      return;
    }

    try {
      const message = await driverHandle.handle.recv();
      if (!message) throw new Error("No message received from widget");

      return message;
    } catch (error) {
      console.error("Failed to receive message from widget:", error);
      throw error;
    }
  }
}

