import { CallOverlayService } from "modules/call/service/CallOverlayService";
import { NativeModules, Platform } from "react-native";
import RNCallKeep, { CONSTANTS, type IOptions } from "react-native-callkeep";

type ActiveCallInfo = {
  roomId: string;
  roomName: string;
  senderDisplayName: string;
};

type CallKeepBufferedEvent = {
  name?: string;
  data?: {
    callUUID?: string;
    uuid?: string;
  };
};

/** Generate a UUID v4 string for CallKit call identifiers */
const generateUUID = (): string => {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
};

export class CallKitService {
  private static isSetUp = false;
  private static activeCallMap = new Map<string, ActiveCallInfo>();
  private static ringTimeouts = new Map<
    string,
    ReturnType<typeof setTimeout>
  >();

  /** Configure RNCallKeep. Must be called once before displaying calls. */
  static async setup() {
    if (Platform.OS !== "ios" || this.isSetUp) return;

    try {
      const options: IOptions = {
        ios: {
          appName: "Cloak",
          supportsVideo: true,
          includesCallsInRecents: true,
        },
        /**TODO: Android options are not configured yet */
        android: {
          alertTitle: "Cloak",
          alertDescription: "You have a call",
          cancelButton: "Decline",
          okButton: "Answer",
          additionalPermissions: [],
        },
      };
      await RNCallKeep.setup(options);
      this.isSetUp = true;
      this.registerEventListeners();
    } catch (error) {
      console.error("[CallKit] Failed to setup:", error);
    }
  }

  /** Display the native iOS incoming call screen */
  static displayIncomingCall(callInfo: {
    roomId: string;
    roomName: string;
    senderDisplayName: string;
  }) {
    if (Platform.OS !== "ios") return;

    const callUUID = generateUUID();

    this.activeCallMap.set(callUUID, {
      roomId: callInfo.roomId,
      roomName: callInfo.roomName,
      senderDisplayName: callInfo.senderDisplayName,
    });

    RNCallKeep.displayIncomingCall(
      callUUID,
      callInfo.roomId,
      callInfo.senderDisplayName,
      "generic",
      true,
    );

    // Ring timeout: auto-end after 30 seconds if not answered
    const timeout = setTimeout(() => {
      RNCallKeep.reportEndCallWithUUID(
        callUUID,
        CONSTANTS.END_CALL_REASONS.UNANSWERED,
      );
      this.activeCallMap.delete(callUUID);
      this.ringTimeouts.delete(callUUID);
      void this.clearNativePendingCall();
    }, 30000);

    this.ringTimeouts.set(callUUID, timeout);
  }

  /** End all active CallKit calls and clean up state */
  static endAllCalls() {
    if (Platform.OS !== "ios") return;

    RNCallKeep.endAllCalls();

    for (const [, timeout] of this.ringTimeouts) {
      clearTimeout(timeout);
    }
    this.ringTimeouts.clear();
    this.activeCallMap.clear();
    void this.clearNativePendingCall();
  }

  /** Check if there is an active ringing call */
  static hasActiveCall() {
    return this.activeCallMap.size > 0;
  }

  /** Check if we already have a ringing call for a given room */
  static isRingingForRoom(roomId: string) {
    for (const [, info] of this.activeCallMap) {
      if (info.roomId === roomId) return true;
    }

    return false;
  }

  /** Track UUIDs we are ending ourselves so the endCall listener can ignore them */
  private static selfEndingCalls = new Set<string>();

  /**
   * Pending call answered from a killed-state cold launch.
   * Populated in answerCall when activeCallMap is empty (JS never called displayIncomingCall).
   * Consumed by Splash after session restore to reopen the call overlay.
   */
  private static pendingAnsweredCall: {
    roomId: string;
    roomName: string;
  } | null = null;

  static consumePendingAnsweredCall() {
    const call = this.pendingAnsweredCall;
    this.pendingAnsweredCall = null;
    return call;
  }

  private static async consumeNativePendingCall() {
    try {
      const pending =
        await NativeModules.VoIPPushModule?.consumePendingCall?.();
      if (!pending?.roomId) return null;
      return {
        roomId: pending.roomId,
        roomName: pending.roomName ?? pending.roomId,
      };
    } catch {
      return null;
    }
  }

  private static async clearNativePendingCall() {
    try {
      await NativeModules.VoIPPushModule?.clearPendingCall?.();
    } catch {
      // Best effort cleanup only.
    }
  }

  private static extractCallUUID(event: { callUUID?: string; uuid?: string }) {
    return event.callUUID ?? event.uuid;
  }

  private static async handleAnswerCall(event: {
    callUUID?: string;
    uuid?: string;
  }) {
    const callUUID = this.extractCallUUID(event);
    if (!callUUID) return;

    let callInfo = this.activeCallMap.get(callUUID);
    let consumedNativePendingCall = false;

    // Cold-start: activeCallMap is empty because JS never called displayIncomingCall.
    // AppDelegate stored roomId/roomName in UserDefaults when the VoIP push arrived —
    // retrieve it now so Splash can reopen the call overlay after session restore.
    if (!callInfo) {
      const pending = await this.consumeNativePendingCall();
      if (!pending?.roomId) return;
      consumedNativePendingCall = true;
      callInfo = {
        roomId: pending.roomId,
        roomName: pending.roomName,
        senderDisplayName: pending.roomName,
      };
      this.pendingAnsweredCall = {
        roomId: callInfo.roomId,
        roomName: callInfo.roomName,
      };
    }

    // Clear ring timeout
    const timeout = this.ringTimeouts.get(callUUID);
    if (timeout) {
      clearTimeout(timeout);
      this.ringTimeouts.delete(callUUID);
    }

    // CRITICAL WORKAROUND: CallKit takes exclusive audio control which
    // breaks WebView-based audio/video. We must end the CallKit session
    // before opening Element Call WebView.
    // We use endCall() (not reportEndCallWithUUID) so the call is properly
    // recorded as "answered" in iPhone's Phone recents, not as "missed".
    // A delay lets CallKit register the answered state first.
    this.selfEndingCalls.add(callUUID);

    setTimeout(() => {
      RNCallKeep.endCall(callUUID);
    }, 300);

    // Navigate only for warm/foreground answers where call metadata came from JS memory.
    // For cold-start answers, Splash is the single owner of redirect via pendingAnsweredCall.
    if (!consumedNativePendingCall) {
      setTimeout(() => {
        CallOverlayService.openCall(callInfo.roomId, callInfo.roomName);
      }, 800);
    } else {
      console.log("[CallKit] cold-start redirect delegated to Splash");
    }

    if (!consumedNativePendingCall) {
      void this.clearNativePendingCall();
    }

    this.activeCallMap.delete(callUUID);
  }

  private static async handleEndCall(event: {
    callUUID?: string;
    uuid?: string;
  }) {
    const callUUID = this.extractCallUUID(event);
    if (!callUUID) return;

    // If we ended this call ourselves (after answering), just clean up the flag
    if (this.selfEndingCalls.has(callUUID)) {
      this.selfEndingCalls.delete(callUUID);
      return;
    }

    const callInfo = this.activeCallMap.get(callUUID);

    // Clear ring timeout
    const timeout = this.ringTimeouts.get(callUUID);
    if (timeout) {
      clearTimeout(timeout);
      this.ringTimeouts.delete(callUUID);
    }

    if (callInfo) {
      this.activeCallMap.delete(callUUID);
      return;
    }

    // Cold-start decline: JS has no activeCallMap entry, but native pending call
    // data may still exist from the VoIP push. Clear it to avoid stale redirects.
    await this.clearNativePendingCall();
  }

  private static registerEventListeners() {
    // User answered the call from CallKit UI
    RNCallKeep.addEventListener("answerCall", async (event) => {
      await this.handleAnswerCall(event);
    });

    // User declined the call from CallKit UI (or call ended by us after answer)
    RNCallKeep.addEventListener("endCall", async (event) => {
      await this.handleEndCall(event);
    });

    // Replay events that occurred before JS listeners were registered.
    // This is crucial for cold launches from CallKit where answer/end actions
    // can arrive before React Native initializes.
    RNCallKeep.addEventListener(
      "didLoadWithEvents",
      async (payload: unknown) => {
        const bufferedPayload = payload as
          | CallKeepBufferedEvent[]
          | { events?: CallKeepBufferedEvent[] };
        const events = Array.isArray(bufferedPayload)
          ? bufferedPayload
          : bufferedPayload.events;

        if (!Array.isArray(events)) return;

        for (const event of events) {
          const data = event?.data ?? {};
          if (event?.name === "RNCallKeepPerformAnswerCallAction") {
            await this.handleAnswerCall(data);
            continue;
          }
          if (event?.name === "RNCallKeepPerformEndCallAction") {
            await this.handleEndCall(data);
          }
        }
      },
    );

    // User tapped a call entry in iPhone's Phone recents to call back
    RNCallKeep.addEventListener(
      "didReceiveStartCallAction",
      ({ handle }: { handle: string }) => {
        if (!handle) return;
        CallOverlayService.openCall(handle);

        // End the outgoing CallKit session since Element Call WebView handles it
        RNCallKeep.endAllCalls();
      },
    );
  }
}

