8	import { isIpad } from "shared/utils";
9	import { IpadSidebar } from "../ipad-sidebar";
10	
11	const SIDEBAR_WIDTH = 440;
12	
13	const FULLSCREEN_ROUTES: (keyof Routes)[] = [
14	  "splash",
15	  "welcome",
16	  "login",
17	  "onboarding",
18	  "notificationsIntro",
19	  "serverSelect",
20	  "confirmIdentity",
