26	  "oidcResetWebView",
27	];
28	
29	export const IpadLayoutWrapper: React.FC<PropsWithChildren> = ({
30	  children,
31	}) => {
32	  const ipad = isIpad();
33	  const splashFinished = useAtomValue(NavigationAtoms.splashFinished);
34	  const matrixClient = useAtomValue(MatrixAtoms.matrixClient);
35	  const [currentRoute, setCurrentRoute] = useState<string | undefined>(
36	    undefined,
37	  );
38	
39	  const showSidebar =
40	    ipad &&
41	    splashFinished &&
42	    matrixClient !== null &&
43	    !FULLSCREEN_ROUTES.includes(currentRoute as keyof Routes);
44	
45	  const transition = useRef(
46	    animateParallel(
47	      { marginLeft: [0, SIDEBAR_WIDTH] },
48	      { duration: 350, easing: Easing.out(Easing.cubic), native: false },
49	    ),
50	  ).current;
51	
52	  useEffect(() => {
53	    if (!NavigationContainerRef?.isReady()) return;
54	    NavigationContainerRef.addListener("state", () => {
55	      setCurrentRoute(NavigationContainerRef?.getCurrentRoute()?.name);
56	    });
57	  }, [NavigationContainerRef?.isReady()]);
58	
59	  useEffect(() => {
60	    if (showSidebar) {
61	      setTimeout(() => transition.start(), 200);
62	    } else transition.reverse();
63	  }, [showSidebar]);
64	
65	  return (
66	    <Block flex={1}>
67	      <Block flex={1} animations={transition.animations}>
68	        {children}
69	      </Block>
70	      {showSidebar && <IpadSidebar />}
71	    </Block>
72	  );
73	};
